package com.example.mid1;

import static android.content.Context.MODE_PRIVATE;

import android.content.Intent;
import android.content.SharedPreferences;
import android.os.Bundle;

import androidx.annotation.NonNull;
import androidx.annotation.Nullable;
import androidx.fragment.app.Fragment;

import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;

import com.google.android.material.button.MaterialButton;

/**
 * Account fragment displaying read-only user information (hard-coded fields).
 * Also provides a logout button that clears the login state and returns to the splash screen.
 */
public class AccountFragment extends Fragment {

    @Override
    public View onCreateView(LayoutInflater inflater, ViewGroup container,
                             Bundle savedInstanceState) {
        return inflater.inflate(R.layout.fragment_account, container, false);
    }

    @Override
    public void onViewCreated(@NonNull View view, @Nullable Bundle savedInstanceState) {
        super.onViewCreated(view, savedInstanceState);

        MaterialButton btnLogout = view.findViewById(R.id.btn_account_logout);

        // Logout: clear login state and navigate back to splash
        btnLogout.setOnClickListener(v -> logout());
    }

    /** Clears the user.isLogin flag and restarts the app from the splash screen. */
    private void logout() {
        SharedPreferences prefs = requireActivity().getSharedPreferences("user", MODE_PRIVATE);
        prefs.edit().putBoolean("user.isLogin", false).apply();

        startActivity(new Intent(requireContext(), splash.class));
        requireActivity().finish();
    }
}

package com.example.mid1;

import static android.content.Context.MODE_PRIVATE;

import android.content.Intent;
import android.content.SharedPreferences;
import android.os.Bundle;

import androidx.annotation.NonNull;
import androidx.annotation.Nullable;
import androidx.fragment.app.Fragment;
import androidx.lifecycle.ViewModelProvider;

import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.ProgressBar;
import android.widget.TextView;
import android.widget.Toast;

import com.google.android.material.button.MaterialButton;

/**
 * Account fragment displaying user information from Firebase.
 * Also provides a logout button that clears the login state and returns to the splash screen.
 */
public class AccountFragment extends Fragment {

    private TextView tvName, tvEmail, tvPhone, tvAddress, tvGender, tvDob, tvCountry, tvAccountType;
    private ProgressBar progressBar;
    private AuthViewModel authViewModel;

    @Override
    public View onCreateView(LayoutInflater inflater, ViewGroup container,
                             Bundle savedInstanceState) {
        return inflater.inflate(R.layout.fragment_account, container, false);
    }

    @Override
    public void onViewCreated(@NonNull View view, @Nullable Bundle savedInstanceState) {
        super.onViewCreated(view, savedInstanceState);

        tvName = view.findViewById(R.id.tv_account_name);
        tvEmail = view.findViewById(R.id.tv_account_email);
        tvPhone = view.findViewById(R.id.tv_account_phone);
        tvAddress = view.findViewById(R.id.tv_account_address);
        tvGender = view.findViewById(R.id.tv_account_gender);
        tvDob = view.findViewById(R.id.tv_account_dob);
        tvCountry = view.findViewById(R.id.tv_account_country);
        tvAccountType = view.findViewById(R.id.tv_account_type);
        progressBar = view.findViewById(R.id.progressBar_account);

        MaterialButton btnLogout = view.findViewById(R.id.btn_account_logout);

        // Initialize ViewModel
        authViewModel = new ViewModelProvider(requireActivity()).get(AuthViewModel.class);

        // Load user data from SharedPreferences
        loadUserData();

        // Observe user data from Firebase
        authViewModel.getUser().observe(getViewLifecycleOwner(), user -> {
            if (user != null) {
                displayUserData(user);
                // Save to SharedPreferences
                SharedPreferences prefs = requireActivity().getSharedPreferences("user", MODE_PRIVATE);
                SharedPreferences.Editor editor = prefs.edit();
                editor.putString("user.name", user.getName());
                editor.putString("user.phone", user.getPhone());
                editor.putString("user.address", user.getAddress());
                editor.putString("user.gender", user.getGender());
                editor.putString("user.dob", user.getDob());
                editor.putString("user.country", user.getCountry());
                editor.apply();
            }
        });

        // Logout: clear login state and navigate back to splash
        btnLogout.setOnClickListener(v -> logout());
    }

    private void loadUserData() {
        SharedPreferences prefs = requireActivity().getSharedPreferences("user", MODE_PRIVATE);
        String uid = prefs.getString("user.uid", "");
        String name = prefs.getString("user.name", "Name not available");
        String email = prefs.getString("user.email", "Email not available");
        String phone = prefs.getString("user.phone", "Phone not available");
        String address = prefs.getString("user.address", "Address not available");
        String gender = prefs.getString("user.gender", "Gender not available");
        String dob = prefs.getString("user.dob", "DOB not available");
        String country = prefs.getString("user.country", "Country not available");
        String accountType = prefs.getString("user.accountType", "Buyer");

        // Display data
        tvName.setText(name);
        tvEmail.setText(email);
        tvPhone.setText(phone);
        tvAddress.setText(address);
        tvGender.setText(gender);
        tvDob.setText(dob);
        tvCountry.setText(country);
        tvAccountType.setText(accountType);

        // Fetch fresh data from Firebase if uid exists
        if (!uid.isEmpty()) {
            authViewModel.fetchUserData(uid);
        }
    }

    private void displayUserData(User user) {
        tvName.setText(user.getName());
        tvEmail.setText(user.getEmail());
        tvPhone.setText(user.getPhone());
        tvAddress.setText(user.getAddress());
        tvGender.setText(user.getGender());
        tvDob.setText(user.getDob());
        tvCountry.setText(user.getCountry());
        tvAccountType.setText(user.getAccountType());
    }

    /**
     * Clears the user.isLogin flag and restarts the app from the splash screen.
     */
    private void logout() {
        SharedPreferences prefs = requireActivity().getSharedPreferences("user", MODE_PRIVATE);
        prefs.edit().putBoolean("user.isLogin", false).apply();

        // Sign out from Firebase
        authViewModel.signOut();

        startActivity(new Intent(requireContext(), splash.class));
        requireActivity().finish();
    }
}

package com.example.mid1;

import android.content.Intent;
import android.os.Bundle;
import android.view.View;
import android.widget.ImageView;
import android.widget.ProgressBar;
import android.widget.TextView;

import androidx.activity.EdgeToEdge;
import androidx.appcompat.app.AppCompatActivity;
import androidx.core.graphics.Insets;
import androidx.core.view.ViewCompat;
import androidx.core.view.WindowInsetsCompat;

import com.bumptech.glide.Glide;
import com.google.android.material.button.MaterialButton;
import com.google.android.material.textfield.TextInputEditText;

import androidx.lifecycle.ViewModelProvider;

/**
 * Activity for adding/editing products
 */
public class AddProductActivity extends AppCompatActivity {

    private TextInputEditText etProductName;
    private TextInputEditText etProductDescription;
    private TextInputEditText etProductCategory;
    private TextInputEditText etProductPrice;
    private TextInputEditText etProductStock;
    private TextInputEditText etProductImageUrl;
    private ImageView ivProductPreview;
    private MaterialButton btnSave;
    private MaterialButton btnCancel;
    private ProgressBar pbLoading;
    private TextView tvError;

    private ProductViewModel productViewModel;
    private Product currentProduct;
    private String productId;
    private boolean isEditMode = false;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        EdgeToEdge.enable(this);
        setContentView(R.layout.activity_add_product);

        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main),
                (v, insets) -> {
                    Insets systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars());
                    v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom);
                    return insets;
                });

        init();
        setupListeners();

        // Check if we're editing an existing product
        if (getIntent().hasExtra("product_id")) {
            isEditMode = true;
            productId = getIntent().getStringExtra("product_id");
            loadProduct(productId);
        }
    }

    private void init() {
        etProductName = findViewById(R.id.et_product_name);
        etProductDescription = findViewById(R.id.et_product_description);
        etProductCategory = findViewById(R.id.et_product_category);
        etProductPrice = findViewById(R.id.et_product_price);
        etProductStock = findViewById(R.id.et_product_stock);
        etProductImageUrl = findViewById(R.id.et_product_image_url);
        ivProductPreview = findViewById(R.id.iv_product_preview);
        btnSave = findViewById(R.id.btn_save);
        btnCancel = findViewById(R.id.btn_cancel);
        pbLoading = findViewById(R.id.pb_loading);
        tvError = findViewById(R.id.tv_error);

        productViewModel = new ViewModelProvider(this).get(ProductViewModel.class);
    }

    private void setupListeners() {
        btnSave.setOnClickListener(v -> saveProduct());
        btnCancel.setOnClickListener(v -> finish());

        etProductImageUrl.setOnFocusChangeListener((v, hasFocus) -> {
            if (!hasFocus) {
                loadImagePreview();
            }
        });
    }

    private void loadProduct(String productId) {
        productViewModel.getProductById(productId);
        productViewModel.getCurrentProduct().observe(this, product -> {
            if (product != null) {
                currentProduct = product;
                populateFields();
            }
        });

        productViewModel.getLoading().observe(this, isLoading -> {
            pbLoading.setVisibility(isLoading ? View.VISIBLE : View.GONE);
        });

        productViewModel.getError().observe(this, error -> {
            if (error != null && !error.isEmpty()) {
                showError(error);
            }
        });
    }

    private void populateFields() {
        if (currentProduct != null) {
            etProductName.setText(currentProduct.getName());
            etProductDescription.setText(currentProduct.getDescription());
            etProductCategory.setText(currentProduct.getCategory());
            etProductPrice.setText(String.valueOf(currentProduct.getPrice()));
            etProductStock.setText(String.valueOf(currentProduct.getStock()));
            etProductImageUrl.setText(currentProduct.getImageUrl());

            // Load image preview
            if (currentProduct.getImageUrl() != null && !currentProduct.getImageUrl().isEmpty()) {
                Glide.with(this)
                        .load(currentProduct.getImageUrl())
                        .placeholder(R.drawable.ic_menu)
                        .error(R.drawable.ic_menu)
                        .into(ivProductPreview);
            }
        }
    }

    private void loadImagePreview() {
        String imageUrl = etProductImageUrl.getText().toString().trim();
        if (imageUrl.isEmpty()) {
            ivProductPreview.setImageResource(R.drawable.ic_menu);
            return;
        }

        Glide.with(this)
                .load(imageUrl)
                .placeholder(R.drawable.ic_menu)
                .error(R.drawable.ic_menu)
                .into(ivProductPreview);
    }

    private void saveProduct() {
        String name = etProductName.getText().toString().trim();
        String description = etProductDescription.getText().toString().trim();
        String category = etProductCategory.getText().toString().trim();
        String imageUrl = etProductImageUrl.getText().toString().trim();

        // Validation
        if (!validateInputs(name, description, category, imageUrl)) {
            return;
        }

        try {
            double price = Double.parseDouble(etProductPrice.getText().toString().trim());
            int stock = Integer.parseInt(etProductStock.getText().toString().trim());

            if (price <= 0) {
                showError("Price must be greater than 0");
                return;
            }

            if (stock < 0) {
                showError("Stock cannot be negative");
                return;
            }

            Product product = new Product(name, description, category, price, stock, imageUrl);

            pbLoading.setVisibility(View.VISIBLE);

            if (isEditMode) {
                // Update existing product
                productViewModel.updateProduct(productId, product,
                        new ProductRepository.OnProductUpdatedListener() {
                            @Override
                            public void onSuccess() {
                                pbLoading.setVisibility(View.GONE);
                                setResult(RESULT_OK);
                                finish();
                            }

                            @Override
                            public void onFailure(String error) {
                                pbLoading.setVisibility(View.GONE);
                                showError(error);
                            }
                        });
            } else {
                // Add new product
                productViewModel.addProduct(product,
                        new ProductRepository.OnProductAddedListener() {
                            @Override
                            public void onSuccess(String productId) {
                                pbLoading.setVisibility(View.GONE);
                                setResult(RESULT_OK);
                                finish();
                            }

                            @Override
                            public void onFailure(String error) {
                                pbLoading.setVisibility(View.GONE);
                                showError(error);
                            }
                        });
            }
        } catch (NumberFormatException e) {
            showError("Invalid price or stock value");
        }
    }

    private boolean validateInputs(String name, String description, String category, String imageUrl) {
        if (name.isEmpty()) {
            showError("Product name is required");
            return false;
        }

        if (description.isEmpty()) {
            showError("Product description is required");
            return false;
        }

        if (category.isEmpty()) {
            showError("Category is required");
            return false;
        }

        if (etProductPrice.getText().toString().trim().isEmpty()) {
            showError("Price is required");
            return false;
        }

        if (etProductStock.getText().toString().trim().isEmpty()) {
            showError("Stock quantity is required");
            return false;
        }

        if (imageUrl.isEmpty()) {
            showError("Image URL is required");
            return false;
        }

        return true;
    }

    private void showError(String message) {
        tvError.setText(message);
        tvError.setVisibility(View.VISIBLE);
    }
}

package com.example.mid1;

import androidx.lifecycle.MutableLiveData;
import com.google.firebase.auth.FirebaseAuth;
import com.google.firebase.auth.FirebaseUser;
import com.google.firebase.database.DatabaseReference;
import com.google.firebase.database.FirebaseDatabase;

/**
 * Repository layer for authentication operations
 * Handles Firebase Auth and Realtime Database operations
 */
public class AuthRepository {
    private static AuthRepository instance;
    private FirebaseAuth firebaseAuth;
    private DatabaseReference databaseReference;

    // LiveData for UI updates
    public MutableLiveData<String> loadingStateLiveData = new MutableLiveData<>();
    public MutableLiveData<String> errorMessageLiveData = new MutableLiveData<>();
    public MutableLiveData<User> userLiveData = new MutableLiveData<>();
    public MutableLiveData<Boolean> authStateLiveData = new MutableLiveData<>();

    private AuthRepository() {
        firebaseAuth = FirebaseAuth.getInstance();
        databaseReference = FirebaseDatabase.getInstance().getReference("users");
    }

    public static synchronized AuthRepository getInstance() {
        if (instance == null) {
            instance = new AuthRepository();
        }
        return instance;
    }

    /**
     * Register/Signup user with Firebase Auth and store user data in Realtime Database
     */
    public void signUp(String email, String password, String name, String phone,
                       String address, String gender, String dob, String country, String accountType) {
        loadingStateLiveData.setValue("Registering...");

        firebaseAuth.createUserWithEmailAndPassword(email, password)
                .addOnCompleteListener(task -> {
                    if (task.isSuccessful()) {
                        FirebaseUser firebaseUser = firebaseAuth.getCurrentUser();
                        if (firebaseUser != null) {
                            String uid = firebaseUser.getUid();

                            // Create User object with all data
                            User user = new User(email, name, phone, address, gender, dob, country, accountType);
                            user.setUid(uid);

                            // Store in Firebase Realtime Database
                            databaseReference.child(uid).setValue(user)
                                    .addOnSuccessListener(aVoid -> {
                                        loadingStateLiveData.setValue("Success");
                                        userLiveData.setValue(user);
                                        authStateLiveData.setValue(true);
                                    })
                                    .addOnFailureListener(e -> {
                                        errorMessageLiveData.setValue("Failed to save user data: " + e.getMessage());
                                        loadingStateLiveData.setValue("Error");
                                    });
                        }
                    } else {
                        String errorMsg = task.getException() != null ? 
                                task.getException().getMessage() : "Signup failed";
                        errorMessageLiveData.setValue(errorMsg);
                        loadingStateLiveData.setValue("Error");
                    }
                });
    }

    /**
     * Login user with Firebase Auth
     */
    public void signIn(String email, String password) {
        loadingStateLiveData.setValue("Logging in...");

        firebaseAuth.signInWithEmailAndPassword(email, password)
                .addOnCompleteListener(task -> {
                    if (task.isSuccessful()) {
                        FirebaseUser firebaseUser = firebaseAuth.getCurrentUser();
                        if (firebaseUser != null) {
                            String uid = firebaseUser.getUid();
                            // Fetch user data from database
                            fetchUserData(uid);
                        }
                    } else {
                        String errorMsg = task.getException() != null ? 
                                task.getException().getMessage() : "Login failed";
                        errorMessageLiveData.setValue(errorMsg);
                        loadingStateLiveData.setValue("Error");
                    }
                });
    }

    /**
     * Fetch user data from Firebase Realtime Database
     */
    public void fetchUserData(String uid) {
        databaseReference.child(uid).get()
                .addOnCompleteListener(task -> {
                    if (task.isSuccessful()) {
                        User user = task.getResult().getValue(User.class);
                        if (user != null) {
                            user.setUid(uid);
                            loadingStateLiveData.setValue("Success");
                            userLiveData.setValue(user);
                            authStateLiveData.setValue(true);
                        } else {
                            errorMessageLiveData.setValue("User data not found");
                            loadingStateLiveData.setValue("Error");
                        }
                    } else {
                        errorMessageLiveData.setValue("Failed to fetch user data: " + task.getException().getMessage());
                        loadingStateLiveData.setValue("Error");
                    }
                });
    }

    /**
     * Get current logged-in user
     */
    public FirebaseUser getCurrentUser() {
        return firebaseAuth.getCurrentUser();
    }

    /**
     * Check if user is already logged in
     */
    public boolean isUserLoggedIn() {
        return firebaseAuth.getCurrentUser() != null;
    }

    /**
     * Logout user
     */
    public void signOut() {
        firebaseAuth.signOut();
        authStateLiveData.setValue(false);
    }
}

package com.example.mid1;

import androidx.lifecycle.LiveData;
import androidx.lifecycle.ViewModel;

/**
 * ViewModel for authentication operations
 * Provides data to UI while surviving configuration changes
 */
public class AuthViewModel extends ViewModel {
    private AuthRepository authRepository;

    public AuthViewModel() {
        authRepository = AuthRepository.getInstance();
    }

    // LiveData fields
    public LiveData<String> getLoadingState() {
        return authRepository.loadingStateLiveData;
    }

    public LiveData<String> getErrorMessage() {
        return authRepository.errorMessageLiveData;
    }

    public LiveData<User> getUser() {
        return authRepository.userLiveData;
    }

    public LiveData<Boolean> getAuthState() {
        return authRepository.authStateLiveData;
    }

    /**
     * Perform signup
     */
    public void signUp(String email, String password, String name, String phone,
                       String address, String gender, String dob, String country, String accountType) {
        authRepository.signUp(email, password, name, phone, address, gender, dob, country, accountType);
    }

    /**
     * Perform login
     */
    public void signIn(String email, String password) {
        authRepository.signIn(email, password);
    }

    /**
     * Fetch user data
     */
    public void fetchUserData(String uid) {
        authRepository.fetchUserData(uid);
    }

    /**
     * Check if user is logged in
     */
    public boolean isUserLoggedIn() {
        return authRepository.isUserLoggedIn();
    }

    /**
     * Logout
     */
    public void signOut() {
        authRepository.signOut();
    }

    /**
     * Get current user
     */
    public String getCurrentUserId() {
        return authRepository.getCurrentUser() != null ? authRepository.getCurrentUser().getUid() : null;
    }
}

