package com.example.mid1;

/**
 * Product model class representing a seller's product
 */
public class Product {
    private String id;
    private String name;
    private String description;
    private String category;
    private double price;
    private int stock;
    private String imageUrl;
    private long createdAt;
    private String sellerId;

    // Default constructor (required for Firebase)
    public Product() {
    }

    // Constructor with parameters
    public Product(String name, String description, String category, double price, int stock, String imageUrl) {
        this.name = name;
        this.description = description;
        this.category = category;
        this.price = price;
        this.stock = stock;
        this.imageUrl = imageUrl;
        this.createdAt = System.currentTimeMillis();
    }

    // Getters and Setters
    public String getId() {
        return id;
    }

    public void setId(String id) {
        this.id = id;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public String getDescription() {
        return description;
    }

    public void setDescription(String description) {
        this.description = description;
    }

    public String getCategory() {
        return category;
    }

    public void setCategory(String category) {
        this.category = category;
    }

    public double getPrice() {
        return price;
    }

    public void setPrice(double price) {
        this.price = price;
    }

    public int getStock() {
        return stock;
    }

    public void setStock(int stock) {
        this.stock = stock;
    }

    public String getImageUrl() {
        return imageUrl;
    }

    public void setImageUrl(String imageUrl) {
        this.imageUrl = imageUrl;
    }

    public long getCreatedAt() {
        return createdAt;
    }

    public void setCreatedAt(long createdAt) {
        this.createdAt = createdAt;
    }

    public String getSellerId() {
        return sellerId;
    }

    public void setSellerId(String sellerId) {
        this.sellerId = sellerId;
    }
}

package com.example.mid1;

import android.content.Context;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.ImageView;
import android.widget.TextView;

import androidx.annotation.NonNull;
import androidx.recyclerview.widget.RecyclerView;

import com.bumptech.glide.Glide;

import java.util.ArrayList;
import java.util.List;

/**
 * RecyclerView adapter for displaying seller's products
 */
public class ProductAdapter extends RecyclerView.Adapter<ProductAdapter.ProductViewHolder> {
    private Context context;
    private List<Product> products;
    private OnProductClickListener onProductClickListener;
    private OnProductDeleteListener onProductDeleteListener;

    public ProductAdapter(Context context) {
        this.context = context;
        this.products = new ArrayList<>();
    }

    public void setProducts(List<Product> products) {
        this.products = products;
        notifyDataSetChanged();
    }

    public void setOnProductClickListener(OnProductClickListener listener) {
        this.onProductClickListener = listener;
    }

    public void setOnProductDeleteListener(OnProductDeleteListener listener) {
        this.onProductDeleteListener = listener;
    }

    @NonNull
    @Override
    public ProductViewHolder onCreateViewHolder(@NonNull ViewGroup parent, int viewType) {
        View view = LayoutInflater.from(context).inflate(R.layout.item_product, parent, false);
        return new ProductViewHolder(view);
    }

    @Override
    public void onBindViewHolder(@NonNull ProductViewHolder holder, int position) {
        Product product = products.get(position);
        if (product != null) {
            holder.bind(product);
        }
    }

    @Override
    public int getItemCount() {
        return products.size();
    }

    public class ProductViewHolder extends RecyclerView.ViewHolder {
        private ImageView ivProductImage;
        private TextView tvProductName;
        private TextView tvProductPrice;
        private TextView tvProductCategory;
        private TextView tvProductStock;
        private View btnDelete;
        private View btnEdit;

        public ProductViewHolder(@NonNull View itemView) {
            super(itemView);
            ivProductImage = itemView.findViewById(R.id.iv_product_image);
            tvProductName = itemView.findViewById(R.id.tv_product_name);
            tvProductPrice = itemView.findViewById(R.id.tv_product_price);
            tvProductCategory = itemView.findViewById(R.id.tv_product_category);
            tvProductStock = itemView.findViewById(R.id.tv_product_stock);
            btnDelete = itemView.findViewById(R.id.btn_delete);
            btnEdit = itemView.findViewById(R.id.btn_edit);
        }

        public void bind(Product product) {
            tvProductName.setText(product.getName());
            tvProductPrice.setText(String.format("$%.2f", product.getPrice()));
            tvProductCategory.setText(product.getCategory());
            tvProductStock.setText(String.format("Stock: %d", product.getStock()));

            // Load image using Glide
            if (product.getImageUrl() != null && !product.getImageUrl().isEmpty()) {
                Glide.with(context)
                        .load(product.getImageUrl())
                        .placeholder(R.drawable.ic_menu)
                        .error(R.drawable.ic_menu)
                        .into(ivProductImage);
            } else {
                ivProductImage.setImageResource(R.drawable.ic_menu);
            }

            // Item click listener
            itemView.setOnClickListener(v -> {
                if (onProductClickListener != null) {
                    onProductClickListener.onProductClick(product);
                }
            });

            // Delete button click listener
            btnDelete.setOnClickListener(v -> {
                if (onProductDeleteListener != null) {
                    onProductDeleteListener.onProductDelete(product);
                }
            });

            // Edit button click listener
            btnEdit.setOnClickListener(v -> {
                if (onProductClickListener != null) {
                    onProductClickListener.onProductEdit(product);
                }
            });
        }
    }

    public interface OnProductClickListener {
        void onProductClick(Product product);
        void onProductEdit(Product product);
    }

    public interface OnProductDeleteListener {
        void onProductDelete(Product product);
    }
}

package com.example.mid1;

import android.content.Intent;
import android.os.Bundle;
import android.view.View;
import android.widget.ImageView;
import android.widget.ProgressBar;
import android.widget.TextView;

import androidx.activity.EdgeToEdge;
import androidx.appcompat.app.AppCompatActivity;
import androidx.core.graphics.Insets;
import androidx.core.view.ViewCompat;
import androidx.core.view.WindowInsetsCompat;

import com.bumptech.glide.Glide;
import com.google.android.material.button.MaterialButton;

import androidx.lifecycle.ViewModelProvider;

/**
 * Activity for displaying product details
 */
public class ProductDescriptionActivity extends AppCompatActivity {

    private ImageView ivProductImage;
    private TextView tvProductName;
    private TextView tvProductCategory;
    private TextView tvProductPrice;
    private TextView tvProductStock;
    private TextView tvProductDescription;
    private MaterialButton btnBack;
    private MaterialButton btnEdit;
    private ProgressBar pbLoading;

    private ProductViewModel productViewModel;
    private Product currentProduct;
    private String productId;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        EdgeToEdge.enable(this);
        setContentView(R.layout.activity_product_description);

        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main),
                (v, insets) -> {
                    Insets systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars());
                    v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom);
                    return insets;
                });

        init();
        setupListeners();
        loadProduct();
    }

    private void init() {
        ivProductImage = findViewById(R.id.iv_product_image);
        tvProductName = findViewById(R.id.tv_product_name);
        tvProductCategory = findViewById(R.id.tv_product_category);
        tvProductPrice = findViewById(R.id.tv_product_price);
        tvProductStock = findViewById(R.id.tv_product_stock);
        tvProductDescription = findViewById(R.id.tv_product_description);
        btnBack = findViewById(R.id.btn_back);
        btnEdit = findViewById(R.id.btn_edit);
        pbLoading = findViewById(R.id.pb_loading);

        productViewModel = new ViewModelProvider(this).get(ProductViewModel.class);
        productId = getIntent().getStringExtra("product_id");
    }

    private void setupListeners() {
        btnBack.setOnClickListener(v -> finish());
        btnEdit.setOnClickListener(v -> {
            if (currentProduct != null) {
                Intent intent = new Intent(this, AddProductActivity.class);
                intent.putExtra("product_id", currentProduct.getId());
                startActivityForResult(intent, 1);
            }
        });
    }

    private void loadProduct() {
        if (productId == null) {
            finish();
            return;
        }

        pbLoading.setVisibility(View.VISIBLE);
        productViewModel.getProductById(productId);

        productViewModel.getCurrentProduct().observe(this, product -> {
            if (product != null) {
                currentProduct = product;
                displayProduct();
                pbLoading.setVisibility(View.GONE);
            }
        });

        productViewModel.getError().observe(this, error -> {
            if (error != null && !error.isEmpty()) {
                pbLoading.setVisibility(View.GONE);
                finish();
            }
        });
    }

    private void displayProduct() {
        if (currentProduct == null) {
            return;
        }

        tvProductName.setText(currentProduct.getName());
        tvProductCategory.setText(currentProduct.getCategory());
        tvProductPrice.setText(String.format("$%.2f", currentProduct.getPrice()));
        tvProductStock.setText(String.valueOf(currentProduct.getStock()));
        tvProductDescription.setText(currentProduct.getDescription());

        // Load image using Glide
        if (currentProduct.getImageUrl() != null && !currentProduct.getImageUrl().isEmpty()) {
            Glide.with(this)
                    .load(currentProduct.getImageUrl())
                    .placeholder(R.drawable.ic_menu)
                    .error(R.drawable.ic_menu)
                    .into(ivProductImage);
        } else {
            ivProductImage.setImageResource(R.drawable.ic_menu);
        }
    }

    @Override
    protected void onActivityResult(int requestCode, int resultCode, Intent data) {
        super.onActivityResult(requestCode, resultCode, data);
        if (resultCode == RESULT_OK) {
            // Reload product after edit
            pbLoading.setVisibility(View.VISIBLE);
            productViewModel.getProductById(productId);
        }
    }
}

package com.example.mid1;

import androidx.lifecycle.MutableLiveData;

import com.google.firebase.auth.FirebaseAuth;
import com.google.firebase.database.DataSnapshot;
import com.google.firebase.database.DatabaseError;
import com.google.firebase.database.DatabaseReference;
import com.google.firebase.database.FirebaseDatabase;
import com.google.firebase.database.ValueEventListener;

import java.util.ArrayList;
import java.util.List;

/**
 * Repository for handling product-related Firebase operations
 */
public class ProductRepository {
    private FirebaseDatabase firebaseDatabase;
    private FirebaseAuth firebaseAuth;
    private DatabaseReference productsRef;
    private MutableLiveData<List<Product>> productsLiveData;
    private MutableLiveData<String> errorLiveData;
    private MutableLiveData<Boolean> loadingLiveData;

    public ProductRepository() {
        this.firebaseDatabase = FirebaseDatabase.getInstance();
        this.firebaseAuth = FirebaseAuth.getInstance();
        this.productsRef = firebaseDatabase.getReference("products");
        this.productsLiveData = new MutableLiveData<>();
        this.errorLiveData = new MutableLiveData<>();
        this.loadingLiveData = new MutableLiveData<>();
    }

    public MutableLiveData<List<Product>> getProducts() {
        return productsLiveData;
    }

    public MutableLiveData<String> getError() {
        return errorLiveData;
    }

    public MutableLiveData<Boolean> getLoading() {
        return loadingLiveData;
    }

    /**
     * Load all products for the current seller
     */
    public void loadSellerProducts() {
        loadingLiveData.setValue(true);
        String sellerId = firebaseAuth.getCurrentUser().getUid();

        productsRef.orderByChild("sellerId").equalTo(sellerId)
                .addValueEventListener(new ValueEventListener() {
                    @Override
                    public void onDataChange(DataSnapshot dataSnapshot) {
                        loadingLiveData.setValue(false);
                        List<Product> products = new ArrayList<>();

                        for (DataSnapshot snapshot : dataSnapshot.getChildren()) {
                            Product product = snapshot.getValue(Product.class);
                            if (product != null) {
                                product.setId(snapshot.getKey());
                                products.add(product);
                            }
                        }

                        productsLiveData.setValue(products);
                    }

                    @Override
                    public void onCancelled(DatabaseError databaseError) {
                        loadingLiveData.setValue(false);
                        errorLiveData.setValue(databaseError.getMessage());
                    }
                });
    }

    /**
     * Add a new product to Firebase
     */
    public void addProduct(Product product, OnProductAddedListener listener) {
        loadingLiveData.setValue(true);
        String sellerId = firebaseAuth.getCurrentUser().getUid();
        product.setSellerId(sellerId);

        String productId = productsRef.push().getKey();
        if (productId != null) {
            productsRef.child(productId).setValue(product)
                    .addOnSuccessListener(aVoid -> {
                        loadingLiveData.setValue(false);
                        if (listener != null) {
                            listener.onSuccess(productId);
                        }
                    })
                    .addOnFailureListener(e -> {
                        loadingLiveData.setValue(false);
                        errorLiveData.setValue(e.getMessage());
                        if (listener != null) {
                            listener.onFailure(e.getMessage());
                        }
                    });
        }
    }

    /**
     * Update an existing product
     */
    public void updateProduct(String productId, Product product, OnProductUpdatedListener listener) {
        loadingLiveData.setValue(true);
        product.setId(productId);

        productsRef.child(productId).setValue(product)
                .addOnSuccessListener(aVoid -> {
                    loadingLiveData.setValue(false);
                    if (listener != null) {
                        listener.onSuccess();
                    }
                })
                .addOnFailureListener(e -> {
                    loadingLiveData.setValue(false);
                    errorLiveData.setValue(e.getMessage());
                    if (listener != null) {
                        listener.onFailure(e.getMessage());
                    }
                });
    }

    /**
     * Delete a product
     */
    public void deleteProduct(String productId, OnProductDeletedListener listener) {
        loadingLiveData.setValue(true);

        productsRef.child(productId).removeValue()
                .addOnSuccessListener(aVoid -> {
                    loadingLiveData.setValue(false);
                    if (listener != null) {
                        listener.onSuccess();
                    }
                })
                .addOnFailureListener(e -> {
                    loadingLiveData.setValue(false);
                    errorLiveData.setValue(e.getMessage());
                    if (listener != null) {
                        listener.onFailure(e.getMessage());
                    }
                });
    }

    /**
     * Get a single product by ID
     */
    public void getProductById(String productId, MutableLiveData<Product> productLiveData) {
        loadingLiveData.setValue(true);

        productsRef.child(productId).addListenerForSingleValueEvent(new ValueEventListener() {
            @Override
            public void onDataChange(DataSnapshot dataSnapshot) {
                loadingLiveData.setValue(false);
                Product product = dataSnapshot.getValue(Product.class);
                if (product != null) {
                    product.setId(dataSnapshot.getKey());
                }
                productLiveData.setValue(product);
            }

            @Override
            public void onCancelled(DatabaseError databaseError) {
                loadingLiveData.setValue(false);
                errorLiveData.setValue(databaseError.getMessage());
            }
        });
    }

    // Listener interfaces
    public interface OnProductAddedListener {
        void onSuccess(String productId);
        void onFailure(String error);
    }

    public interface OnProductUpdatedListener {
        void onSuccess();
        void onFailure(String error);
    }

    public interface OnProductDeletedListener {
        void onSuccess();
        void onFailure(String error);
    }
}

package com.example.mid1;

import androidx.lifecycle.LiveData;
import androidx.lifecycle.MutableLiveData;
import androidx.lifecycle.ViewModel;

import java.util.List;

/**
 * ViewModel for managing product-related data and operations
 */
public class ProductViewModel extends ViewModel {
    private ProductRepository productRepository;
    private LiveData<List<Product>> productsLiveData;
    private LiveData<String> errorLiveData;
    private LiveData<Boolean> loadingLiveData;
    private MutableLiveData<Product> currentProductLiveData;

    public ProductViewModel() {
        productRepository = new ProductRepository();
        productsLiveData = productRepository.getProducts();
        errorLiveData = productRepository.getError();
        loadingLiveData = productRepository.getLoading();
        currentProductLiveData = new MutableLiveData<>();
    }

    public LiveData<List<Product>> getProducts() {
        return productsLiveData;
    }

    public LiveData<String> getError() {
        return errorLiveData;
    }

    public LiveData<Boolean> getLoading() {
        return loadingLiveData;
    }

    public MutableLiveData<Product> getCurrentProduct() {
        return currentProductLiveData;
    }

    /**
     * Load all products for the current seller
     */
    public void loadSellerProducts() {
        productRepository.loadSellerProducts();
    }

    /**
     * Add a new product
     */
    public void addProduct(Product product, ProductRepository.OnProductAddedListener listener) {
        productRepository.addProduct(product, listener);
    }

    /**
     * Update an existing product
     */
    public void updateProduct(String productId, Product product, 
                             ProductRepository.OnProductUpdatedListener listener) {
        productRepository.updateProduct(productId, product, listener);
    }

    /**
     * Delete a product
     */
    public void deleteProduct(String productId, ProductRepository.OnProductDeletedListener listener) {
        productRepository.deleteProduct(productId, listener);
    }

    /**
     * Get a product by ID
     */
    public void getProductById(String productId) {
        productRepository.getProductById(productId, currentProductLiveData);
    }
}

package com.example.mid1;

import static android.content.Context.MODE_PRIVATE;

import android.content.SharedPreferences;
import android.os.Bundle;
import androidx.annotation.NonNull;
import androidx.annotation.Nullable;
import androidx.fragment.app.Fragment;
import androidx.lifecycle.ViewModelProvider;

import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.TextView;

/**
 * Seller Account Fragment
 * Displays seller account details
 */
public class SellerAccountFragment extends Fragment {

    private TextView tvName, tvEmail, tvPhone, tvAddress, tvCountry;
    private AuthViewModel authViewModel;

    public SellerAccountFragment() {
    }

    @Override
    public View onCreateView(LayoutInflater inflater, ViewGroup container,
                             Bundle savedInstanceState) {
        return inflater.inflate(R.layout.fragment_seller_account, container, false);
    }

    @Override
    public void onViewCreated(@NonNull View view, @Nullable Bundle savedInstanceState) {
        super.onViewCreated(view, savedInstanceState);

        tvName = view.findViewById(R.id.tv_seller_name_detail);
        tvEmail = view.findViewById(R.id.tv_seller_email_detail);
        tvPhone = view.findViewById(R.id.tv_seller_phone_detail);
        tvAddress = view.findViewById(R.id.tv_seller_address_detail);
        tvCountry = view.findViewById(R.id.tv_seller_country_detail);

        authViewModel = new ViewModelProvider(requireActivity()).get(AuthViewModel.class);

        // Load data from SharedPreferences
        loadSellerData();

        // Observe user data from Firebase
        authViewModel.getUser().observe(getViewLifecycleOwner(), user -> {
            if (user != null) {
                displaySellerData(user);
            }
        });
    }

    private void loadSellerData() {
        SharedPreferences prefs = requireActivity().getSharedPreferences("user", MODE_PRIVATE);
        String name = prefs.getString("user.name", "Name not available");
        String email = prefs.getString("user.email", "Email not available");
        String phone = prefs.getString("user.phone", "Phone not available");
        String address = prefs.getString("user.address", "Address not available");
        String country = prefs.getString("user.country", "Country not available");

        tvName.setText(name);
        tvEmail.setText(email);
        tvPhone.setText(phone);
        tvAddress.setText(address);
        tvCountry.setText(country);

        // Fetch fresh data
        String uid = prefs.getString("user.uid", "");
        if (!uid.isEmpty()) {
            authViewModel.fetchUserData(uid);
        }
    }

    private void displaySellerData(User user) {
        tvName.setText(user.getName());
        tvEmail.setText(user.getEmail());
        tvPhone.setText(user.getPhone());
        tvAddress.setText(user.getAddress());
        tvCountry.setText(user.getCountry());
    }
}

package com.example.mid1;

import android.content.Intent;
import android.content.SharedPreferences;
import android.os.Bundle;
import android.widget.TextView;

import androidx.activity.EdgeToEdge;
import androidx.appcompat.app.ActionBarDrawerToggle;
import androidx.appcompat.app.AppCompatActivity;
import androidx.appcompat.widget.Toolbar;
import androidx.core.graphics.Insets;
import androidx.core.view.ViewCompat;
import androidx.core.view.WindowInsetsCompat;
import androidx.drawerlayout.widget.DrawerLayout;
import androidx.fragment.app.Fragment;
import androidx.fragment.app.FragmentManager;
import androidx.fragment.app.FragmentTransaction;

import com.google.android.material.navigation.NavigationView;

/**
 * Seller Dashboard Activity
 * Main activity for sellers with drawer navigation and theme support
 */
public class SellerDashboard extends AppCompatActivity {

    private DrawerLayout drawerLayout;
    private NavigationView navigationView;
    private Toolbar toolbar;
    private ActionBarDrawerToggle toggle;
    private ThemeManager themeManager;
    private SharedPreferences sPref;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        // Initialize theme manager before setContentView
        themeManager = ThemeManager.getInstance(this);

        super.onCreate(savedInstanceState);
        EdgeToEdge.enable(this);
        setContentView(R.layout.activity_seller_dashboard);

        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main), (v, insets) -> {
            Insets systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars());
            v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom);
            return insets;
        });

        init();
        setupDrawerNavigation();
        loadSellerProfile();

        // Load home fragment by default
        if (savedInstanceState == null) {
            loadFragment(new SellerHomeFragment(), "Home");
        }
    }

    private void init() {
        drawerLayout = findViewById(R.id.drawer_layout);
        navigationView = findViewById(R.id.nav_view);
        toolbar = findViewById(R.id.toolbar);

        setSupportActionBar(toolbar);
        sPref = getSharedPreferences("user", MODE_PRIVATE);
    }

    private void setupDrawerNavigation() {
        toggle = new ActionBarDrawerToggle(
                this, drawerLayout, toolbar,
                R.string.nav_open, R.string.nav_close);
        drawerLayout.addDrawerListener(toggle);
        toggle.syncState();

        navigationView.setNavigationItemSelectedListener(item -> {
            int itemId = item.getItemId();

            if (itemId == R.id.nav_home) {
                loadFragment(new SellerHomeFragment(), "Home");
            } else if (itemId == R.id.nav_order_history) {
                loadFragment(new OrderHistoryFragment(), "Order History");
            } else if (itemId == R.id.nav_account) {
                loadFragment(new SellerAccountFragment(), "Account");
            } else if (itemId == R.id.nav_theme_toggle) {
                toggleTheme();
            } else if (itemId == R.id.nav_logout) {
                logout();
            }

            drawerLayout.closeDrawers();
            return true;
        });
    }

    private void loadFragment(Fragment fragment, String title) {
        toolbar.setTitle(title);

        FragmentManager fragmentManager = getSupportFragmentManager();
        FragmentTransaction transaction = fragmentManager.beginTransaction();
        transaction.setCustomAnimations(
                android.R.anim.fade_in,
                android.R.anim.fade_out,
                android.R.anim.fade_in,
                android.R.anim.fade_out
        );
        transaction.replace(R.id.fragment_container, fragment);
        transaction.addToBackStack(null);
        transaction.commit();
    }

    private void loadSellerProfile() {
        String sellerName = sPref.getString("user.name", "Seller");
        String sellerEmail = sPref.getString("user.email", "seller@example.com");

        // Update drawer header
        NavigationView navView = findViewById(R.id.nav_view);
        if (navView != null && navView.getHeaderCount() > 0) {
            TextView tvName = navView.getHeaderView(0).findViewById(R.id.tv_drawer_name);
            TextView tvEmail = navView.getHeaderView(0).findViewById(R.id.tv_drawer_email);

            if (tvName != null) tvName.setText(sellerName);
            if (tvEmail != null) tvEmail.setText(sellerEmail);
        }
    }

    private void toggleTheme() {
        themeManager.toggleTheme();
        // Recreate activity to apply theme
        recreate();
    }

    private void logout() {
        // Clear login state
        sPref.edit().putBoolean("user.isLogin", false).apply();

        // Navigate to splash screen
        startActivity(new Intent(this, splash.class));
        finish();
    }
}

package com.example.mid1;

import android.content.Intent;
import android.os.Bundle;
import androidx.annotation.NonNull;
import androidx.annotation.Nullable;
import androidx.fragment.app.Fragment;
import androidx.lifecycle.ViewModelProvider;
import androidx.recyclerview.widget.GridLayoutManager;
import androidx.recyclerview.widget.RecyclerView;

import android.app.AlertDialog;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.LinearLayout;
import android.widget.ProgressBar;
import android.widget.TextView;

import com.google.android.material.floatingactionbutton.FloatingActionButton;

import java.util.List;

/**
 * Seller Home Fragment
 * Displays seller home dashboard with products list
 */
public class SellerHomeFragment extends Fragment {

    private RecyclerView rvProducts;
    private FloatingActionButton fabAddProduct;
    private TextView tvTotalProducts;
    private TextView tvTotalStock;
    private ProgressBar pbLoading;
    private LinearLayout llEmptyState;
    private ProductAdapter productAdapter;
    private ProductViewModel productViewModel;

    public SellerHomeFragment() {
    }

    @Override
    public View onCreateView(LayoutInflater inflater, ViewGroup container,
                             Bundle savedInstanceState) {
        return inflater.inflate(R.layout.fragment_seller_home, container, false);
    }

    @Override
    public void onViewCreated(@NonNull View view, @Nullable Bundle savedInstanceState) {
        super.onViewCreated(view, savedInstanceState);

        init(view);
        setupRecyclerView();
        setupProductAdapter();
        setupObservers();
        setupFABListener();

        // Load products
        productViewModel.loadSellerProducts();
    }

    private void init(View view) {
        rvProducts = view.findViewById(R.id.rv_products);
        fabAddProduct = view.findViewById(R.id.fab_add_product);
        tvTotalProducts = view.findViewById(R.id.tv_total_products);
        tvTotalStock = view.findViewById(R.id.tv_total_stock);
        pbLoading = view.findViewById(R.id.pb_loading);
        llEmptyState = view.findViewById(R.id.ll_empty_state);

        productViewModel = new ViewModelProvider(this).get(ProductViewModel.class);
    }

    private void setupRecyclerView() {
        GridLayoutManager layoutManager = new GridLayoutManager(getContext(), 2);
        rvProducts.setLayoutManager(layoutManager);
    }

    private void setupProductAdapter() {
        productAdapter = new ProductAdapter(getContext());
        rvProducts.setAdapter(productAdapter);

        // Handle product click
        productAdapter.setOnProductClickListener(new ProductAdapter.OnProductClickListener() {
            @Override
            public void onProductClick(Product product) {
                Intent intent = new Intent(getContext(), ProductDescriptionActivity.class);
                intent.putExtra("product_id", product.getId());
                startActivity(intent);
            }

            @Override
            public void onProductEdit(Product product) {
                Intent intent = new Intent(getContext(), AddProductActivity.class);
                intent.putExtra("product_id", product.getId());
                startActivityForResult(intent, 1);
            }
        });

        // Handle product delete
        productAdapter.setOnProductDeleteListener(product -> {
            showDeleteConfirmation(product);
        });
    }

    private void setupObservers() {
        // Products observer
        productViewModel.getProducts().observe(getViewLifecycleOwner(), products -> {
            if (products != null) {
                updateUI(products);
            }
        });

        // Loading observer
        productViewModel.getLoading().observe(getViewLifecycleOwner(), isLoading -> {
            pbLoading.setVisibility(isLoading ? View.VISIBLE : View.GONE);
        });

        // Error observer
        productViewModel.getError().observe(getViewLifecycleOwner(), error -> {
            if (error != null && !error.isEmpty()) {
                showErrorDialog(error);
            }
        });
    }

    private void updateUI(List<Product> products) {
        if (products.isEmpty()) {
            rvProducts.setVisibility(View.GONE);
            llEmptyState.setVisibility(View.VISIBLE);
            tvTotalProducts.setText("0");
            tvTotalStock.setText("0");
        } else {
            rvProducts.setVisibility(View.VISIBLE);
            llEmptyState.setVisibility(View.GONE);

            // Update stats
            tvTotalProducts.setText(String.valueOf(products.size()));
            int totalStock = 0;
            for (Product product : products) {
                totalStock += product.getStock();
            }
            tvTotalStock.setText(String.valueOf(totalStock));

            // Update adapter
            productAdapter.setProducts(products);
        }
    }

    private void setupFABListener() {
        fabAddProduct.setOnClickListener(v -> {
            Intent intent = new Intent(getContext(), AddProductActivity.class);
            startActivityForResult(intent, 1);
        });
    }

    @Override
    public void onActivityResult(int requestCode, int resultCode, Intent data) {
        super.onActivityResult(requestCode, resultCode, data);
        if (requestCode == 1 && resultCode == getActivity().RESULT_OK) {
            // Reload products after adding/editing
            productViewModel.loadSellerProducts();
        }
    }

    private void showDeleteConfirmation(Product product) {
        new AlertDialog.Builder(getContext())
                .setTitle("Delete Product")
                .setMessage("Are you sure you want to delete this product?")
                .setPositiveButton("Yes", (dialog, which) -> {
                    deleteProduct(product);
                })
                .setNegativeButton("No", null)
                .show();
    }

    private void deleteProduct(Product product) {
        productViewModel.deleteProduct(product.getId(),
                new ProductRepository.OnProductDeletedListener() {
                    @Override
                    public void onSuccess() {
                        productViewModel.loadSellerProducts();
                    }

                    @Override
                    public void onFailure(String error) {
                        showErrorDialog("Failed to delete product: " + error);
                    }
                });
    }

    private void showErrorDialog(String message) {
        new AlertDialog.Builder(getContext())
                .setTitle("Error")
                .setMessage(message)
                .setPositiveButton("OK", null)
                .show();
    }
}

package com.example.mid1;

import android.content.Context;
import android.content.SharedPreferences;
import androidx.appcompat.app.AppCompatDelegate;

/**
 * Utility class to manage app themes (Light/Dark)
 * Persists theme preference in SharedPreferences
 */
public class ThemeManager {
    private static final String PREFS_NAME = "theme_prefs";
    private static final String THEME_KEY = "selected_theme";
    private static final String THEME_LIGHT = "light";
    private static final String THEME_DARK = "dark";

    private static ThemeManager instance;
    private SharedPreferences sharedPreferences;
    private String currentTheme;

    private ThemeManager(Context context) {
        sharedPreferences = context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE);
        currentTheme = sharedPreferences.getString(THEME_KEY, THEME_LIGHT);
        applyTheme(currentTheme);
    }

    public static synchronized ThemeManager getInstance(Context context) {
        if (instance == null) {
            instance = new ThemeManager(context);
        }
        return instance;
    }

    /**
     * Apply theme globally
     */
    public void applyTheme(String theme) {
        if (THEME_DARK.equals(theme)) {
            AppCompatDelegate.setDefaultNightMode(AppCompatDelegate.MODE_NIGHT_YES);
        } else {
            AppCompatDelegate.setDefaultNightMode(AppCompatDelegate.MODE_NIGHT_NO);
        }
        currentTheme = theme;
        saveThemePreference(theme);
    }

    /**
     * Toggle between light and dark themes
     */
    public void toggleTheme() {
        if (THEME_LIGHT.equals(currentTheme)) {
            applyTheme(THEME_DARK);
        } else {
            applyTheme(THEME_LIGHT);
        }
    }

    /**
     * Get current theme
     */
    public String getCurrentTheme() {
        return currentTheme;
    }

    /**
     * Check if dark theme is active
     */
    public boolean isDarkTheme() {
        return THEME_DARK.equals(currentTheme);
    }

    /**
     * Save theme preference to SharedPreferences
     */
    private void saveThemePreference(String theme) {
        sharedPreferences.edit().putString(THEME_KEY, theme).apply();
    }
}

package com.example.mid1;

/**
 * User model class for Firebase authentication and data storage
 */
public class User {
    private String uid;
    private String email;
    private String name;
    private String phone;
    private String address;
    private String gender;
    private String dob;
    private String country;
    private String accountType; // "Buyer" or "Seller"

    // Default constructor for Firebase
    public User() {
    }

    public User(String email, String name, String phone, String address, 
                String gender, String dob, String country, String accountType) {
        this.email = email;
        this.name = name;
        this.phone = phone;
        this.address = address;
        this.gender = gender;
        this.dob = dob;
        this.country = country;
        this.accountType = accountType;
    }

    // Getters and Setters
    public String getUid() {
        return uid;
    }

    public void setUid(String uid) {
        this.uid = uid;
    }

    public String getEmail() {
        return email;
    }

    public void setEmail(String email) {
        this.email = email;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public String getPhone() {
        return phone;
    }

    public void setPhone(String phone) {
        this.phone = phone;
    }

    public String getAddress() {
        return address;
    }

    public void setAddress(String address) {
        this.address = address;
    }

    public String getGender() {
        return gender;
    }

    public void setGender(String gender) {
        this.gender = gender;
    }

    public String getDob() {
        return dob;
    }

    public void setDob(String dob) {
        this.dob = dob;
    }

    public String getCountry() {
        return country;
    }

    public void setCountry(String country) {
        this.country = country;
    }

    public String getAccountType() {
        return accountType;
    }

    public void setAccountType(String accountType) {
        this.accountType = accountType;
    }
}

